    #[test]
    fn graph_materialization_preserves_multiple_boundary_memberships() {
        let (_temp, mut store) = initialized_store();
        let mut plan = definition("example");
        let template = plan.nodes.values().next().expect("template").clone();
        plan.nodes.clear();
        plan.entries.clear();
        plan.exits.clear();
        for index in 0..40 {
            let mut node = template.clone();
            node.id = format!("boundary-{index:02}");
            if index % 2 == 0 {
                plan.entries.push(node.id.clone());
            }
            if index % 3 == 0 {
                plan.exits.push(node.id.clone());
            }
            plan.nodes.insert(node.id.clone(), node);
        }
        let transaction = store.connection.transaction().expect("transaction");
        transaction
            .execute_batch(
                "DELETE FROM workflow_run_graph_edges WHERE run_id = 'run-1';
             DELETE FROM workflow_run_graph_nodes WHERE run_id = 'run-1';
             DELETE FROM workflow_run_graphs WHERE run_id = 'run-1';",
            )
            .expect("replace fixture graph");
        run_graph::materialize(&transaction, "run-1", &plan).expect("materialize");
        transaction.commit().expect("commit");
        let nodes = store.run_graph_nodes("run-1", None, 100).expect("nodes");
        assert_eq!(nodes.len(), 40);
        for node in nodes {
            assert_eq!(node.entry, plan.entries.contains(&node.node.id));
            assert_eq!(node.exit, plan.exits.contains(&node.node.id));
            assert_eq!(node.node, plan.nodes[&node.node.id]);
        }
    }

    #[test]
    fn initial_node_pages_resume_without_duplicates_or_mutation() {
        let (_temp, store) = initialized_store();
        let template = store
            .run_graph_nodes("run-1", None, 1)
            .expect("template")
            .remove(0)
            .node;
        for index in 0..205 {
            let mut node = template.clone();
            node.id = format!("page-{index:03}");
            store.connection.execute(
                "INSERT INTO workflow_run_graph_nodes (run_id, node_id, revision, node_json, is_entry, is_exit) VALUES ('run-1', ?1, 1, ?2, 0, 0)",
                rusqlite::params![node.id, serde_json::to_string(&node).expect("serialize")],
            ).expect("insert node");
        }
        let before = store.connection.total_changes();
        let mut cursor = None;
        let mut ids = Vec::new();
        loop {
            let page = store
                .run_graph_nodes("run-1", cursor.as_deref(), usize::MAX)
                .expect("page");
            assert!(page.len() <= 100);
            if page.is_empty() {
                break;
            }
            cursor = page.last().map(|item| item.node.id.clone());
            ids.extend(page.into_iter().map(|item| item.node.id));
        }
        assert_eq!(ids.len(), 206);
        assert!(ids.windows(2).all(|pair| pair[0] < pair[1]));
        for index in 0..205 {
            assert!(ids.binary_search(&format!("page-{index:03}")).is_ok());
        }
        assert!(store.run_graph_nodes("missing", Some(""), 10).is_err());
        assert!(
            store
                .run_graph_nodes("missing", None, 10)
                .expect("missing")
                .is_empty()
        );
        assert_eq!(store.connection.total_changes(), before);
    }

    #[test]
    fn schema_16_index_migration_rolls_back_on_orphaned_graph() {
        let (temp, store) = initialized_store();
        let original_nodes = store
            .run_graph_nodes("run-1", None, 100)
            .expect("original nodes");
        store
            .connection
            .execute_batch(
                "DROP INDEX workflow_run_graph_edges_source;
             ALTER TABLE workflow_activations DROP COLUMN node_revision; UPDATE workflow_store_contract SET schema_version = 16 WHERE contract_id = 1;
             PRAGMA foreign_keys = OFF;
             DELETE FROM workflow_run_graphs WHERE run_id = 'run-1';",
            )
            .expect("orphan graph fixture");
        remove_retirement_fixture(&store);
        drop(store);
        let error = WorkflowStore::migrate_to_current_in_state_dir(temp.path(), 78)
            .expect_err("orphaned graph must reject migration");
        assert!(matches!(error, WorkflowStoreError::InvalidData(message)
            if message == "workflow migration foreign-key verification failed; canonical relationships are inconsistent"));
        let database_path = workflow_database_path(temp.path());
        let backup_path = database_path
            .parent()
            .expect("store directory")
            .join(MIGRATION_BACKUP_DIRECTORY)
            .join("workflow-78.db");
        let backup =
            Connection::open_with_flags(&backup_path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)
                .expect("failed migration retains backup");
        assert_eq!(detected_store_schema(&backup), Some(16));
        let backup_nodes: u64 = backup
            .query_row(
                "SELECT COUNT(*) FROM workflow_run_graph_nodes WHERE run_id = 'run-1'",
                [],
                |row| row.get(0),
            )
            .expect("backed up orphan");
        assert_eq!(backup_nodes, 1);
        let backup_headers: u64 = backup
            .query_row(
                "SELECT COUNT(*) FROM workflow_run_graphs WHERE run_id = 'run-1'",
                [],
                |row| row.get(0),
            )
            .expect("backup preserves absent header");
        assert_eq!(backup_headers, 0);
        drop(backup);
        let failed_backup_bytes = std::fs::read(&backup_path).expect("retain backup bytes");
        let connection =
            Connection::open(workflow_database_path(temp.path())).expect("inspect fixture");
        assert_eq!(detected_store_schema(&connection), Some(16));
        let indexes: u64 = connection
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE name = 'workflow_run_graph_edges_source'",
                [],
                |row| row.get(0),
            )
            .expect("index rollback");
        assert_eq!(indexes, 0);
        let nodes: u64 = connection
            .query_row(
                "SELECT COUNT(*) FROM workflow_run_graph_nodes WHERE run_id = 'run-1'",
                [],
                |row| row.get(0),
            )
            .expect("orphan preserved");
        assert_eq!(nodes, 1);
        let headers: u64 = connection
            .query_row(
                "SELECT COUNT(*) FROM workflow_run_graphs WHERE run_id = 'run-1'",
                [],
                |row| row.get(0),
            )
            .expect("no reconstruction");
        assert_eq!(headers, 0);
        connection
            .execute(
                "INSERT INTO workflow_run_graphs (run_id, revision) VALUES ('run-1', 1)",
                [],
            )
            .expect("explicit fixture restoration");
        drop(connection);
        let receipt = WorkflowStore::migrate_to_current_in_state_dir(temp.path(), 79)
            .expect("retry after restoration");
        assert_eq!(
            std::fs::read(&backup_path).expect("failed backup after retry"),
            failed_backup_bytes
        );
        assert_ne!(receipt.backup_path, backup_path);
        assert_eq!(receipt.previous_schema_version, 16);
        assert_eq!(receipt.new_schema_version, WORKFLOW_STORE_SCHEMA_VERSION);
        let reopened =
            WorkflowStore::open_in_state_dir(temp.path()).expect("reopen migrated store");
        let nodes = reopened.run_graph_nodes("run-1", None, 100).expect("nodes");
        assert_eq!(nodes, original_nodes);
        assert!(
            reopened
                .run_graph_outgoing_edges("run-1", &original_nodes[0].node.id, None, 1)
                .expect("source index available")
                .is_empty()
        );
    }

    fn assert_backup_nodes(backup: &Connection, expected: &[RunGraphNode]) {
        let mut statement = backup.prepare(
            "SELECT node_id, revision, node_json, is_entry, is_exit FROM workflow_run_graph_nodes WHERE run_id = 'run-1' ORDER BY node_id",
        ).expect("backup node query");
        let actual = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, u64>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, bool>(3)?,
                    row.get::<_, bool>(4)?,
                ))
            })
            .expect("backup nodes")
            .collect::<Result<Vec<_>, _>>()
            .expect("decode backup nodes");
        assert_eq!(actual.len(), expected.len());
        for ((id, revision, payload, entry, exit), node) in actual.iter().zip(expected) {
            assert_eq!(id, &node.node.id);
            assert_eq!(*revision, node.revision);
            assert_eq!((*entry, *exit), (node.entry, node.exit));
            assert_eq!(
                serde_json::from_str::<bcode_workflow::NodeDefinition>(payload)
                    .expect("node payload"),
                node.node
            );
        }
    }

    fn assert_schema_16_backup_edge(backup: &Connection, edge: &bcode_workflow::EdgeDefinition) {
        assert_eq!(detected_store_schema(backup), Some(16));
        let revision: u64 = backup
            .query_row(
                "SELECT revision FROM workflow_run_graphs WHERE run_id = 'run-1'",
                [],
                |row| row.get(0),
            )
            .expect("backed up graph revision");
        assert_eq!(revision, 1);
        let (edge_id, revision, source, target, payload): (u64, u64, String, String, String) = backup.query_row(
            "SELECT edge_id, revision, source_node_id, target_node_id, edge_json FROM workflow_run_graph_edges WHERE run_id = 'run-1' AND edge_id = 42",
            [], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        ).expect("backed up edge");
        assert_eq!((edge_id, revision), (42, 1));
        assert_eq!((&source, &target), (&edge.from, &edge.to));
        assert_eq!(
            &serde_json::from_str::<bcode_workflow::EdgeDefinition>(&payload)
                .expect("edge payload"),
            edge
        );
    }

    fn add_migration_exit_node(
        store: &WorkflowStore,
        source: &bcode_workflow::NodeDefinition,
    ) -> bcode_workflow::NodeDefinition {
        let mut target = source.clone();
        target.id = "migration-target".to_owned();
        store.connection.execute(
            "UPDATE workflow_run_graph_nodes SET is_entry = 1, is_exit = 0 WHERE run_id = 'run-1' AND node_id = ?1",
            [&source.id],
        ).expect("entry-only source");
        store
            .connection
            .execute(
                "INSERT INTO workflow_run_graph_nodes (run_id, node_id, revision, node_json, is_entry, is_exit) VALUES ('run-1', ?1, 1, ?2, 0, 1)",
                rusqlite::params![
                    target.id,
                    serde_json::to_string(&target).expect("serialize target")
                ],
            )
            .expect("persist target");
        target
    }

