    #[test]
    fn schema_16_migration_adds_source_index_without_rebuilding_graph() {
        let (temp, store) = initialized_store();
        let nodes = store.run_graph_nodes("run-1", None, 100).expect("nodes");
        let node_id = &nodes[0].node.id;
        let target = add_migration_exit_node(&store, &nodes[0].node);
        let expected_nodes = store
            .run_graph_nodes("run-1", None, 100)
            .expect("all nodes");
        let edge = bcode_workflow::EdgeDefinition {
            from: node_id.clone(),
            to: target.id.clone(),
            kind: bcode_workflow::EdgeKind::Direct,
            transform: None,
        };
        store
            .connection
            .execute(
                "INSERT INTO workflow_run_graph_edges (run_id, edge_id, revision, source_node_id, target_node_id, edge_json) VALUES ('run-1', 42, 1, ?1, ?2, ?3)",
                rusqlite::params![
                    node_id,
                    target.id,
                    serde_json::to_string(&edge).expect("serialize")
                ],
            )
            .expect("persist edge");
        let edges = store.run_graph_edges("run-1", None, 100).expect("edges");
        store
            .connection
            .execute_batch(
                "DROP INDEX workflow_run_graph_edges_source;
             ALTER TABLE workflow_activations DROP COLUMN node_revision; UPDATE workflow_store_contract SET schema_version = 16 WHERE contract_id = 1;",
            )
            .expect("schema 16 fixture");
        remove_retirement_fixture(&store);
        drop(store);
        assert!(WorkflowStore::open_in_state_dir(temp.path()).is_err());
        let receipt = WorkflowStore::migrate_to_current_in_state_dir(temp.path(), 71)
            .expect("explicit migration");
        assert_eq!(receipt.previous_schema_version, 16);
        assert_eq!(receipt.new_schema_version, WORKFLOW_STORE_SCHEMA_VERSION);
        assert_eq!(receipt.migrated_at_ms, 71);
        let backup_bytes = std::fs::read(&receipt.backup_path).expect("receipt backup");
        assert_eq!(receipt.backup_sha256, sha256_hex(&backup_bytes));
        let backup = Connection::open_with_flags(
            &receipt.backup_path,
            rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
        )
        .expect("inspect pre-migration backup");
        assert_schema_16_backup_edge(&backup, &edge);
        assert_backup_nodes(&backup, &expected_nodes);
        drop(backup);
        let store = WorkflowStore::open_in_state_dir(temp.path()).expect("reopen");
        assert_eq!(
            store.run_graph_revision("run-1").expect("graph revision"),
            Some(1)
        );
        assert_eq!(
            store.run_graph_nodes("run-1", None, 100).expect("nodes"),
            expected_nodes
        );
        assert_eq!(
            store
                .run_graph_incoming_edges("run-1", &target.id, None, 100)
                .expect("incoming"),
            edges
        );
        assert!(
            store
                .run_graph_outgoing_edges("run-1", &target.id, None, 100)
                .expect("target outgoing")
                .is_empty()
        );
        assert!(
            store
                .run_graph_incoming_edges("run-1", node_id, None, 100)
                .expect("source incoming")
                .is_empty()
        );
        assert_eq!(
            store
                .run_graph_edges("run-1", None, 100)
                .expect("preserved edges"),
            edges
        );
        assert_eq!(
            store
                .run_graph_outgoing_edges("run-1", node_id, None, 100)
                .expect("indexed edges"),
            edges
        );
        let index_count: u64 = store.connection.query_row(
            "SELECT COUNT(*) FROM sqlite_master WHERE type = 'index' AND name = 'workflow_run_graph_edges_source'",
            [], |row| row.get(0),
        ).expect("source index");
        assert_eq!(index_count, 1);
    }

    #[test]
    fn endpoint_index_damage_is_isolated_by_direction() {
        for source in [true, false] {
            let (temp, store) = initialized_store();
            let node = store
                .run_graph_nodes("run-1", None, 1)
                .expect("node")
                .remove(0)
                .node;
            let edge = bcode_workflow::EdgeDefinition {
                from: node.id.clone(),
                to: node.id.clone(),
                kind: bcode_workflow::EdgeKind::Direct,
                transform: None,
            };
            store
                .connection
                .execute(
                    "INSERT INTO workflow_run_graph_edges (run_id, edge_id, revision, source_node_id, target_node_id, edge_json) VALUES ('run-1', 42, 1, ?1, ?1, ?2)",
                    rusqlite::params![node.id, serde_json::to_string(&edge).expect("serialize")],
                )
                .expect("persist edge");
            store
                .connection
                .execute_batch(if source {
                    "DROP INDEX workflow_run_graph_edges_source;"
                } else {
                    "DROP INDEX workflow_run_graph_edges_target;"
                })
                .expect("damage one index");
            let before = store.connection.total_changes();
            let outgoing = store.run_graph_outgoing_edges("run-1", &node.id, None, 1);
            let incoming = store.run_graph_incoming_edges("run-1", &node.id, None, 1);
            let (damaged, intact) = if source {
                (outgoing, incoming)
            } else {
                (incoming, outgoing)
            };
            assert!(damaged.is_err());
            let intact = intact.expect("other direction remains available");
            assert_eq!(intact.len(), 1);
            assert_eq!(intact[0].edge_id, 42);
            assert_eq!(intact[0].edge, edge);
            assert_eq!(store.connection.total_changes(), before);
            drop(store);
            let reopened =
                WorkflowStore::open_in_state_dir(temp.path()).expect("reopen without repair");
            let before = reopened.connection.total_changes();
            let outgoing = reopened.run_graph_outgoing_edges("run-1", &node.id, None, 1);
            let incoming = reopened.run_graph_incoming_edges("run-1", &node.id, None, 1);
            let (damaged, available) = if source {
                (outgoing, incoming)
            } else {
                (incoming, outgoing)
            };
            assert!(damaged.is_err());
            assert_eq!(available.expect("intact direction after reopen"), intact);
            assert_eq!(reopened.connection.total_changes(), before);
        }
    }

