        assert_eq!(choose.activated[0].node_id, "selected");
        let other_status: String = store
            .connection
            .query_row(
                "SELECT status FROM workflow_activations WHERE run_id = 'conditional-run' AND node_id = 'other'",
                [],
                |row| row.get(0),
            )
            .expect("other status");
        assert_eq!(other_status, "skipped");
